package com.drivique.api.controller;
import com.drivique.api.service.PaymentReceiptService; import java.util.UUID; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/payments") public class PaymentReceiptController {private final PaymentReceiptService service;public PaymentReceiptController(PaymentReceiptService service){this.service=service;} @GetMapping(value="/{id}/receipt",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> receipt(@PathVariable UUID id,Authentication authentication){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=receipt-"+id+".pdf").body(service.download(id,authentication.getName()));}}
